while (!isEmpty("left") && !isEmpty("right")) {
  if (lessOrEqual(front("left"), front("right"))) {
    take("left");      // ties go to the LEFT run
  } else {
    take("right");
  }
}
while (!isEmpty("left")) take("left");   // drain leftovers
while (!isEmpty("right")) take("right");

